import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Menu,
  MenuItem,
  Tooltip,
} from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import AccountCircle from '@mui/icons-material/AccountCircle';
import HomeIcon from '@mui/icons-material/Home';
import { useNavigate } from 'react-router-dom';

function AdminNavbar() {
  const [menuAnchor, setMenuAnchor] = useState(null);
  const [accountAnchor, setAccountAnchor] = useState(null);
  const navigate = useNavigate();

  const openMenu = (event) => setMenuAnchor(event.currentTarget);
  const closeMenu = () => setMenuAnchor(null);

  const openAccount = (event) => setAccountAnchor(event.currentTarget);
  const closeAccount = () => setAccountAnchor(null);

  const handleNavigate = (path) => {
    closeMenu();
    navigate(path);
  };

  const handleAccountNavigate = (path) => {
    closeAccount();
    navigate(path);
  };

  return (
    <AppBar
      position="static"
      sx={{
        background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)',
      }}
    >
      <Toolbar>

        {/* Hamburger Menu */}
        <Tooltip title="Menu">
          <IconButton
            size="large"
            edge="start"
            color="inherit"
            aria-label="menu"
            sx={{ mr: 1 }}
            onClick={openMenu}
          >
            <MenuIcon />
          </IconButton>
        </Tooltip>

        {/* Home Button */}
        <Tooltip title="Dashboard">
          <IconButton
            size="large"
            edge="start"
            color="inherit"
            aria-label="home"
            sx={{ mr: 2 }}
            onClick={() => navigate('/admin-dashboard')}
          >
            <HomeIcon />
          </IconButton>
        </Tooltip>

        {/* Title */}
        <Typography variant="h6" sx={{ flexGrow: 1 }}>
          CMS - DPDP (Admin)
        </Typography>

        {/* Account Icon */}
        <Tooltip title="Admin Account">
          <IconButton
            size="large"
            edge="end"
            color="inherit"
            onClick={openAccount}
          >
            <AccountCircle />
          </IconButton>
        </Tooltip>

        {/* Navigation Menu Items */}
        <Menu anchorEl={menuAnchor} open={Boolean(menuAnchor)} onClose={closeMenu}>
          <MenuItem onClick={() => handleNavigate('/admin-organization-details')}>
            Organization List
          </MenuItem>
          <MenuItem onClick={() => handleNavigate('/admin-total-consents')}>
            Consent List
          </MenuItem>
          <MenuItem onClick={() => handleNavigate('/admin-audit-logs')}>
            Audit Logs
          </MenuItem>
        </Menu>

        {/* Account Menu Items */}
        <Menu anchorEl={accountAnchor} open={Boolean(accountAnchor)} onClose={closeAccount}>
          {/* <MenuItem onClick={() => handleAccountNavigate('/admin/profile-settings')}>
            Profile Settings
          </MenuItem> */}
          <MenuItem onClick={() => handleAccountNavigate('/')}>
            Logout
          </MenuItem>
        </Menu>
      </Toolbar>
    </AppBar>
  );
}

export default AdminNavbar;
