import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Menu,
  MenuItem,
  Tooltip,
} from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import AccountCircle from '@mui/icons-material/AccountCircle';
import HomeIcon from '@mui/icons-material/Home';
import { useNavigate } from 'react-router-dom';

function OrgNavbar() {
  const [menuAnchor, setMenuAnchor] = useState(null);
  const [accountAnchor, setAccountAnchor] = useState(null);
  const navigate = useNavigate();

  const openMenu = (event) => setMenuAnchor(event.currentTarget);
  const closeMenu = () => setMenuAnchor(null);

  const openAccountMenu = (event) => setAccountAnchor(event.currentTarget);
  const closeAccountMenu = () => setAccountAnchor(null);

  const handleNavigate = (path) => {
    closeMenu();
    navigate(path);
  };

  const handleAccountNavigate = (path) => {
    closeAccountMenu();
    navigate(path);
  };

  return (
    <AppBar
      position="static"
      sx={{
        background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)',
      }}
    >
      <Toolbar>
        {/* Hamburger menu */}
        <Tooltip title="Menu">
          <IconButton
            edge="start"
            color="inherit"
            sx={{ mr: 1 }}
            onClick={openMenu}
          >
            <MenuIcon />
          </IconButton>
        </Tooltip>

        {/* Home icon */}
        <Tooltip title="Dashboard">
          <IconButton
            edge="start"
            color="inherit"
            sx={{ mr: 2 }}
            onClick={() => navigate('/organization-dashboard')}
          >
            <HomeIcon />
          </IconButton>
        </Tooltip>

        {/* Title */}
        <Typography variant="h6" sx={{ flexGrow: 1 }}>
          CMS - DPDP (Organization)
        </Typography>

        {/* Account icon */}
        <Tooltip title="Account">
          <IconButton
            edge="end"
            color="inherit"
            onClick={openAccountMenu}
          >
            <AccountCircle />
          </IconButton>
        </Tooltip>

        {/* Hamburger Dropdown Menu */}
        <Menu anchorEl={menuAnchor} open={Boolean(menuAnchor)} onClose={closeMenu}>
          <MenuItem onClick={() => handleNavigate('/organization-details')}>
            Consents
          </MenuItem>
          <MenuItem onClick={() => handleNavigate('/organization-audit-logs')}>
            Audit Logs
          </MenuItem>
        </Menu>

        {/* Account Menu */}
        <Menu
          anchorEl={accountAnchor}
          open={Boolean(accountAnchor)}
          onClose={closeAccountMenu}
        >
          {/* <MenuItem onClick={() => handleAccountNavigate('/org/profile-settings')}>
            Profile Settings
          </MenuItem> */}
          <MenuItem onClick={() => handleAccountNavigate('/')}>
            Logout
          </MenuItem>
        </Menu>
      </Toolbar>
    </AppBar>
  );
}

export default OrgNavbar;
