import React, { useState } from 'react';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import UserNavbar from './user-navbar';

function PendingConsentRequests() {
  const [searchTerm, setSearchTerm] = useState('');
  const [otpDialogOpen, setOtpDialogOpen] = useState(false);
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
  const [otpValue, setOtpValue] = useState('');
  const [otpError, setOtpError] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const [pendingRequests, setPendingRequests] = useState([
    {
      org: 'Retailer A',
      purpose: 'Marketing',
      status: 'Pending',
      requestedAt: '2025-06-01 10:00 AM',
    },
    {
      org: 'Bank B',
      purpose: 'KYC',
      status: 'Pending',
      requestedAt: '2025-06-02 11:30 AM',
    },
    {
      org: 'Ecom C',
      purpose: 'Order Tracking',
      status: 'Pending',
      requestedAt: '2025-06-03 09:15 AM',
    },
    {
      org: 'Hospital D',
      purpose: 'Health Records',
      status: 'Pending',
      requestedAt: '2025-06-04 02:45 PM',
    },
  ]);

  const handleSearchChange = (e) => setSearchTerm(e.target.value);

  const filteredRequests = pendingRequests.filter(
    (request) =>
      request.org.toLowerCase().includes(searchTerm.toLowerCase()) ||
      request.purpose.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAccept = (index) => {
    setSelectedIndex(index);
    setOtpValue('');
    setOtpError('');
    setOtpDialogOpen(true);
  };

  const handleReject = (index) => {
    setSelectedIndex(index);
    setRejectionReason('');
    setRejectDialogOpen(true);
  };

  const confirmRejection = () => {
    const updated = [...pendingRequests];
    updated.splice(selectedIndex, 1);
    setPendingRequests(updated);
    setRejectDialogOpen(false);
  };

  const handleOtpSubmit = () => {
    const correctOtp = '123456'; // Replace with actual OTP logic
    if (otpValue.trim() === correctOtp) {
      const updated = [...pendingRequests];
      updated.splice(selectedIndex, 1);
      setPendingRequests(updated);
      setOtpDialogOpen(false);
    } else {
      setOtpError('Invalid OTP. Please try again.');
    }
  };

  return (
    <Box>
      <UserNavbar />

      <Box sx={{ width: '90%', margin: 'auto', mt: 4 }}>
        {/* DPDP Act Awareness Box */}
        <Box
          sx={{
            p: 2,
            mb: 3,
            backgroundColor: '#fffde7',
            borderLeft: '5px solid #fbc02d',
            borderRadius: 1,
            boxShadow: 1,
          }}
        >
          <Typography variant="h6" fontWeight="bold" gutterBottom>
            🛡️ DPDP Act Awareness
          </Typography>
          <Typography variant="body2">
            Under the <strong>Digital Personal Data Protection (DPDP) Act</strong>, you have full control over your
            data-sharing decisions. Every consent request you accept or reject must be informed and deliberate.
            Accepting means granting permission to an organization to use your personal data for a specific purpose.
            Rejecting will deny them access.
          </Typography>
        </Box>

        <Typography variant="h6" fontWeight="bold" gutterBottom>
          📋 Pending Consent Requests
        </Typography>

        <TextField
          label="Search by Organization or Purpose"
          variant="outlined"
          fullWidth
          margin="normal"
          value={searchTerm}
          onChange={handleSearchChange}
        />

        <TableContainer component={Paper} elevation={4}>
          <Table>
            <TableHead>
              <TableRow sx={{ background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)', }}>
                <TableCell sx={{ color: 'white' }}>Organization</TableCell>
                <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                <TableCell sx={{ color: 'white' }}>Status</TableCell>
                <TableCell sx={{ color: 'white' }}>Requested At</TableCell>
                <TableCell sx={{ color: 'white' }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRequests.map((request, index) => (
                <TableRow key={index}>
                  <TableCell>{request.org}</TableCell>
                  <TableCell>{request.purpose}</TableCell>
                  <TableCell>{request.status}</TableCell>
                  <TableCell>{request.requestedAt}</TableCell>
                  <TableCell>
                    <Button
                      variant="outlined"
                      color="success"
                      size="small"
                      onClick={() => handleAccept(index)}
                    >
                      Accept
                    </Button>
                    <Button
                      variant="outlined"
                      color="error"
                      size="small"
                      sx={{ ml: 1 }}
                      onClick={() => handleReject(index)}
                    >
                      Reject
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
              {filteredRequests.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} align="center">
                    No matching pending requests.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>

        {/* OTP Dialog for Accept */}
        <Dialog open={otpDialogOpen} onClose={() => setOtpDialogOpen(false)}>
          <DialogTitle>OTP Verification</DialogTitle>
          <DialogContent dividers>
            <Typography gutterBottom>
              Enter the OTP sent to your registered contact to confirm accepting this consent request.
            </Typography>
            <TextField
              fullWidth
              label="Enter OTP"
              margin="normal"
              value={otpValue}
              onChange={(e) => setOtpValue(e.target.value)}
              error={!!otpError}
              helperText={otpError}
              autoFocus
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setOtpDialogOpen(false)}>Cancel</Button>
            <Button
              variant="contained"
              color="success"
              disabled={otpValue.trim().length === 0}
              onClick={handleOtpSubmit}
            >
              Confirm
            </Button>
          </DialogActions>
        </Dialog>

        {/* Rejection Dialog */}
        <Dialog open={rejectDialogOpen} onClose={() => setRejectDialogOpen(false)}>
          <DialogTitle>Confirm Rejection</DialogTitle>
          <DialogContent dividers>
            <Typography gutterBottom>
              Are you sure you want to reject this consent request? You may also include a reason (optional).
            </Typography>
            <TextField
              fullWidth
              label="Reason for Rejection"
              margin="normal"
              multiline
              minRows={2}
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
              placeholder="e.g., I don’t want to share my data for marketing."
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setRejectDialogOpen(false)}>Cancel</Button>
            <Button
              variant="contained"
              color="error"
              onClick={confirmRejection}
            >
              Reject Consent
            </Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Box>
  );
}

export default PendingConsentRequests;
