import React, { useState } from 'react';
import {
  Box,
  Tabs,
  Tab,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Link,
  TextField,
  Divider,
  List,
  ListItem,
} from '@mui/material';
import AttachmentIcon from '@mui/icons-material/Attachment';

import DownloadIcon from '@mui/icons-material/Download';
import Tooltip from '@mui/material/Tooltip';
import IconButton from '@mui/material/IconButton';

import OrgNavbar from './organization-navbar';

function OrgIntro() {
  return (
    <Box sx={{ width: '90%', margin: 'auto', mt: 4 }}>
      <Typography variant="h6" fontWeight="bold" gutterBottom>
        📊 Organization Data Control Center
      </Typography>
      <Typography variant="body2" sx={{ mb: 2 }}>
        Track and manage data consents, usage history, and grievances raised by users. Ensure your organization remains fully compliant with the DPDP Act.
      </Typography>
    </Box>
  );
}

function OrgInfoBox() {
  return (
    <Box
      sx={{
        width: '90%',
        margin: 'auto',
        mb: 3,
        p: 2,
        border: '1px solid #e0e0e0',
        borderRadius: 2,
        backgroundColor: '#e3f2fd',
        boxShadow: 1,
      }}
    >
      <Typography variant="body1" fontWeight="bold" gutterBottom>
        🛡️ DPDP Compliance Reminder
      </Typography>
      <Typography variant="body2">
        As a data fiduciary, you are obligated to ensure transparent data usage, maintain user consents, and respond to grievances swiftly.
      </Typography>
    </Box>
  );
}

function OrganizationMetricsDetails() {
  const [tabIndex, setTabIndex] = useState(0);
  const [openModal, setOpenModal] = useState(false);
  const [selectedConsent, setSelectedConsent] = useState(null);

  const [openGrievanceDialog, setOpenGrievanceDialog] = useState(false);
  const [selectedGrievanceId, setSelectedGrievanceId] = useState(null);
  const [threadMessage, setThreadMessage] = useState('');
  const [uploadFileName, setUploadFileName] = useState('');

  const [grievanceThreads, setGrievanceThreads] = useState({
    // Sample initial conversation threads
    1: [
      { sender: 'user', message: 'Data used for unauthorized promotions.', timestamp: '2025-06-03 10:00' },
      { sender: 'org', message: 'We are investigating this issue.', timestamp: '2025-06-03 12:00' },
    ],
    2: [
      { sender: 'user', message: 'Data shared with third parties without consent.', timestamp: '2025-05-20 09:00' },
      { sender: 'org', message: 'This has been resolved as per our records.', timestamp: '2025-05-22 14:00' },
    ],
  });

  const handleTabChange = (event, newValue) => {
    setTabIndex(newValue);
  };

  const handleOpenModal = (consent) => {
    setSelectedConsent(consent);
    setOpenModal(true);
  };

  const handleCloseModal = () => {
    setOpenModal(false);
    setSelectedConsent(null);
  };

  // Data (same as before)
  const consents = [
    {
      user: 'Alice',
      aadhar: 'XXXX-XXXX-1234',
      purpose: 'Marketing',
      date: '2025-06-01',
      expiry: '2026-06-01',
      status: 'Given',
      attachment: 'https://example.com/marketing-consent.pdf',
      history: {
        requested: '2025-05-30',
        accepted: '2025-06-01',
        revoked: null,
      },
    },
    {
      user: 'Bob',
      aadhar: 'XXXX-XXXX-5678',
      purpose: 'KYC',
      date: '2024-05-01',
      expiry: '2025-05-01',
      status: 'Revoked',
      attachment: null,
      history: {
        requested: '2024-04-20',
        accepted: '2024-05-01',
        revoked: '2025-04-28',
      },
    },
    {
      user: 'Charlie',
      aadhar: 'XXXX-XXXX-9999',
      purpose: 'Order Tracking',
      date: '2025-01-15',
      expiry: '2026-01-15',
      status: 'Given',
      attachment: null,
      history: {
        requested: '2025-01-10',
        accepted: '2025-01-15',
        revoked: null,
      },
    },
  ];

  const usageLogs = [
    { user: 'Alice', data: 'Phone, Address', purpose: 'Shipping', time: '2025-06-02 10:00', metadata: 'Web' },
    { user: 'Charles', data: 'Email', purpose: 'Promotions', time: '2025-06-01 09:00', metadata: 'API' },
  ];

  const grievances = [
    {
      id: 1,
      user: 'Alice',
      issue: 'Data used for unauthorized promotions',
      date: '2025-06-03',
      status: 'Pending',
      ticketNumber: 'TCK-1001',
      priority: 'High',
    },
    {
      id: 2,
      user: 'Bob',
      issue: 'Data shared with third parties without consent',
      date: '2025-05-20',
      status: 'Resolved',
      ticketNumber: 'TCK-1002',
      priority: 'Medium',
    },
  ];


  // Open grievance conversation dialog
  const handleOpenGrievanceDialog = (id) => {
    setSelectedGrievanceId(id);
    setThreadMessage('');
    setOpenGrievanceDialog(true);
  };

  const handleCloseGrievanceDialog = () => {
    setOpenGrievanceDialog(false);
    setSelectedGrievanceId(null);
    setThreadMessage('');
  };

  // Send a new message from org in grievance thread
  const handleSendThreadMessage = () => {
    if (!threadMessage.trim()) return;
    const now = new Date();
    const timestamp = now.toISOString().slice(0, 16).replace('T', ' ');

    setGrievanceThreads((prev) => {
      const existingThread = prev[selectedGrievanceId] || [];
      return {
        ...prev,
        [selectedGrievanceId]: [...existingThread, { sender: 'org', message: threadMessage.trim(), timestamp }],
      };
    });

    setThreadMessage('');
  };

  const exportToCSV = (data, filename, headers) => {
    if (!data.length) return;

    const csvRows = [
      headers.join(','),
      ...data.map((row) =>
        headers.map((field) =>
          `"${(row[field] || '').toString().replace(/"/g, '""')}"`
        ).join(',')
      ),
    ];

    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportConsents = () => {
    const headers = ['user', 'aadhar', 'purpose', 'date', 'expiry', 'status'];
    exportToCSV(consents, 'consents.csv', headers);
  };

  const handleExportUsageLogs = () => {
    const headers = ['user', 'data', 'purpose', 'time', 'metadata'];
    exportToCSV(usageLogs, 'data_usage_logs.csv', headers);
  };

  const handleExportGrievances = () => {
    const headers = ['id', 'ticketNumber', 'user', 'issue', 'priority', 'date', 'status'];

    exportToCSV(grievances, 'grievances.csv', headers);
  };


  return (
    <Box>
      <OrgNavbar />
      <OrgIntro />
      <OrgInfoBox />

      <Box sx={{ width: '90%', margin: 'auto', mt: 3 }}>
        <Tabs
          value={tabIndex}
          onChange={handleTabChange}
          textColor="primary"
          indicatorColor="primary"
          sx={{ mb: 3 }}
        >
          <Tab label="Consents Collected" />
          <Tab label="Data Usage Logs" />
          <Tab label="Grievances" />
        </Tabs>

        {/* Tab 1: Consents Collected */}
        {tabIndex === 0 && (
          <>
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow sx={{background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)', }}>
                    <TableCell sx={{ color: 'white' }}>User</TableCell>
                    <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                    <TableCell sx={{ color: 'white' }}>Date</TableCell>
                    <TableCell sx={{ color: 'white' }}>Expiry</TableCell>
                    <TableCell sx={{ color: 'white' }}>Status</TableCell>
                    <TableCell sx={{ color: 'white' }} align='right'>
                      <Tooltip title="Export CSV">
                        <IconButton
                          size="small"
                          onClick={handleExportConsents}
                        >
                          <DownloadIcon sx={{ color: 'white' }} />
                        </IconButton>
                      </Tooltip>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {consents.map((row, i) => (
                    <TableRow key={i}>
                      <TableCell>{row.user}</TableCell>
                      <TableCell>{row.purpose}</TableCell>
                      <TableCell>{row.date}</TableCell>
                      <TableCell>{row.expiry}</TableCell>
                      <TableCell>
                        <Typography color={row.status === 'Given' ? 'green' : 'error'} fontWeight="bold">
                          {row.status}
                        </Typography>
                      </TableCell>
                      <TableCell align='right'>
                        <Button variant="outlined" size="small" onClick={() => handleOpenModal(row)}>
                          View
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </>
          
        )}

        {/* Tab 2: Data Usage Logs */}
        {tabIndex === 1 && (
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow sx={{background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)', }}>
                  <TableCell sx={{ color: 'white' }}>User</TableCell>
                  <TableCell sx={{ color: 'white' }}>Data</TableCell>
                  <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                  <TableCell sx={{ color: 'white' }}>Timestamp</TableCell>
                  <TableCell sx={{ color: 'white' }}>Metadata</TableCell>
                  <TableCell sx={{ color: 'white' }} align='right'>
                    <Tooltip title="Export CSV">
                      <IconButton
                        size="small"
                        onClick={handleExportUsageLogs}
                      >
                        <DownloadIcon sx={{ color: 'white' }} />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {usageLogs.map((log, i) => (
                  <TableRow key={i}>
                    <TableCell>{log.user}</TableCell>
                    <TableCell>{log.data}</TableCell>
                    <TableCell>{log.purpose}</TableCell>
                    <TableCell>{log.time}</TableCell>
                    <TableCell colSpan="2">{log.metadata}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}

        {/* Tab 3: Grievances */}
        {tabIndex === 2 && (
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow sx={{background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)'}}>
                  <TableCell sx={{ color: 'white' }}>Ticket No.</TableCell>
                  <TableCell sx={{ color: 'white' }}>User</TableCell>
                  <TableCell sx={{ color: 'white' }}>Issue</TableCell>
                  <TableCell sx={{ color: 'white' }}>Priority</TableCell>
                  <TableCell sx={{ color: 'white' }}>Date Reported</TableCell>
                  <TableCell sx={{ color: 'white' }}>Status</TableCell>
                  <TableCell sx={{ color: 'white' }} align='right'>
                    <Tooltip title="Export CSV">
                      <IconButton size="small" onClick={handleExportGrievances}>
                        <DownloadIcon sx={{ color: 'white' }} />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>

              </TableHead>
              <TableBody>
                {grievances.map((grievance) => (
                  <TableRow
                    key={grievance.id}
                    hover
                    sx={{ cursor: 'pointer' }}
                    onClick={() => handleOpenGrievanceDialog(grievance.id)}
                  >
                    <TableCell>{grievance.ticketNumber}</TableCell>
                    <TableCell>{grievance.user}</TableCell>
                    <TableCell>{grievance.issue}</TableCell>
                    <TableCell>
                      <Typography
                        fontWeight="bold"
                        color={
                          grievance.priority === 'High'
                            ? 'error'
                            : grievance.priority === 'Medium'
                            ? 'orange'
                            : 'green'
                        }
                      >
                        {grievance.priority}
                      </Typography>
                    </TableCell>
                    <TableCell>{grievance.date}</TableCell>
                    <TableCell>
                      <Typography color={grievance.status === 'Resolved' ? 'green' : 'orange'} fontWeight="bold">
                        {grievance.status}
                      </Typography>
                    </TableCell>
                    <TableCell align="right">
                      <Button
                        variant="outlined"
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleOpenGrievanceDialog(grievance.id);
                        }}
                      >
                        Chat
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}

              </TableBody>
            </Table>
          </TableContainer>
        )}
      </Box>

      {/* Consent Modal */}
      <Dialog open={openModal} onClose={handleCloseModal} maxWidth="sm" fullWidth>
        <DialogTitle>Consent Details</DialogTitle>
        <DialogContent dividers>
          {selectedConsent ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography><strong>User Name:</strong> {selectedConsent.user}</Typography>
              <Typography><strong>Aadhar No:</strong> {selectedConsent.aadhar}</Typography>
              <Typography><strong>Purpose:</strong> {selectedConsent.purpose}</Typography>
              <Typography><strong>Status:</strong> {selectedConsent.status}</Typography>
              <Typography><strong>Date:</strong> {selectedConsent.date}</Typography>
              <Typography><strong>Expiry:</strong> {selectedConsent.expiry}</Typography>

              {selectedConsent.attachment && (
                <Typography>
                  <strong>Attachment:</strong>{' '}
                  <Link href={selectedConsent.attachment} target="_blank" rel="noopener" underline="hover">
                    View Document
                  </Link>
                </Typography>
              )}

              <Box sx={{ mt: 2 }}>
                <Typography variant="h6" gutterBottom>History</Typography>
                <Typography>Requested: {selectedConsent.history.requested || 'N/A'}</Typography>
                <Typography>Accepted: {selectedConsent.history.accepted || 'N/A'}</Typography>
                <Typography>Revoked: {selectedConsent.history.revoked || 'N/A'}</Typography>
              </Box>
            </Box>
          ) : (
            <Typography>No consent selected.</Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseModal}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Grievance Conversation Thread Dialog */}
      <Dialog
        open={openGrievanceDialog}
        onClose={handleCloseGrievanceDialog}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Grievance Conversation Thread</DialogTitle>
        <DialogContent dividers>
          {selectedGrievanceId && (!grievanceThreads[selectedGrievanceId] || grievanceThreads[selectedGrievanceId].length === 0) && (
            <Typography>No messages yet.</Typography>
          )}

          <List sx={{ maxHeight: 300, overflowY: 'auto' }}>
            {selectedGrievanceId &&
              grievanceThreads[selectedGrievanceId]?.map((msg, idx) => (
                <React.Fragment key={idx}>
                  <ListItem
                    sx={{
                      justifyContent: msg.sender === 'org' ? 'flex-end' : 'flex-start',
                      bgcolor: msg.sender === 'org' ? '#c8e6c9' : '#e0e0e0',
                      borderRadius: 2,
                      my: 0.5,
                      px: 2,
                      py: 1,
                      maxWidth: '75%',
                      marginLeft: msg.sender === 'org' ? 'auto' : '0',
                    }}
                  >
                    <Box>
                      <Typography variant="body2" sx={{ whiteSpace: 'pre-line' }}>
                        {msg.message}
                      </Typography>
                      <Typography variant="caption" sx={{ display: 'block', textAlign: 'right' }}>
                        {msg.timestamp}
                      </Typography>
                    </Box>
                  </ListItem>
                  <Divider />
                </React.Fragment>
              ))}
          </List>

          
        </DialogContent>
        <DialogActions sx={{ flexDirection: 'column', alignItems: 'stretch', gap: 1, px: 2, pb: 2 }}>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <TextField
              label="Type your message"
              fullWidth
              multiline
              minRows={2}
              maxRows={4}
              value={threadMessage}
              onChange={(e) => setThreadMessage(e.target.value)}
              sx={{ flex: 1 }}
            />
            <IconButton component="label" sx={{ ml: 1 }}>
              <AttachmentIcon />
              <input
                type="file"
                hidden
                onChange={(e) => {
                  if (e.target.files.length > 0) {
                    setUploadFileName(e.target.files[0].name);
                  }
                }}
              />
            </IconButton>
          </Box>

          {uploadFileName && (
            <Typography variant="caption" sx={{ ml: 1 }}>
              📎 Attached: {uploadFileName}
            </Typography>
          )}

          <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
            <Button
              variant="outlined"
              color="success"
              onClick={() => {
                const updated = grievances.map((g) =>
                  g.id === selectedGrievanceId ? { ...g, status: 'Resolved' } : g
                );
                setGrievanceThreads({ ...grievanceThreads }); // refresh state
                setSelectedGrievanceId(null);
                setOpenGrievanceDialog(false);
              }}
            >
              Mark as Completed
            </Button>

            <Box>
              <Button onClick={handleCloseGrievanceDialog}>Close</Button>
              <Button
                variant="contained"
                onClick={handleSendThreadMessage}
                disabled={!threadMessage.trim()}
                sx={{ ml: 1 }}
              >
                Send
              </Button>
            </Box>
          </Box>
        </DialogActions>

      </Dialog>
    </Box>
  );
}

export default OrganizationMetricsDetails;
